function plan() {
    if (S.prefs.place === "home") return homePlan();
    var lt = lastTrained(), why = [], skipped = [];
    var lastDay = S.log.length ? S.log[S.log.length - 1].day : null;
    var startIdx = lastDay ? (ORDER.indexOf(lastDay) + 1) % 3 : 0;
    var allowed = S.slot === "am" ? ["push", "pull"] : S.slot === "pm" ? ["legs"] : ORDER;

    var cands = allowed.map(function (d) {
      var D = DAYS[d];
      var notReady = D.main.filter(function (m) { return lt[m] && hoursSince(lt[m]) < RECOVER_H; });
      var hurt = D.main.filter(function (m) { return bodyState("m", m); });
      var avail = EX.filter(function (e) { return e.day === d && S.off.indexOf(e.id) < 0 && !exStatus(e).out; });
      var blocked = hurt.length * 2 >= D.main.length || avail.length < 2;
      var rot = (ORDER.indexOf(d) - startIdx + 3) % 3;
      return { d: d, notReady: notReady, hurt: hurt, avail: avail, blocked: blocked, score: notReady.length * 10 + hurt.length * 5 + rot };
    });
    var open = cands.filter(function (c) { return !c.blocked; }).sort(function (a, b) { return a.score - b.score; });

    cands.forEach(function (c) {
      if (!c.blocked) return;
      if (c.hurt.length) { skipped.push(DAYS[c.d].name + ": " + names(c.hurt, MUSCLES) + t("ยังเมื่อยหรือเจ็บ")); return; }
      var why = {};
      EX.forEach(function (e) { if (e.day === c.d && S.off.indexOf(e.id) < 0) { var st = exStatus(e); if (st.out) why[st.out] = 1; } });
      var r = Object.keys(why);
      skipped.push(DAYS[c.d].name + ": " + (r.length ? r.join(" ") + t(" ตัดท่าออกจนเหลือไม่ถึง 2 ท่า") : t("เปิดท่าไว้ไม่ถึง 2 ท่า (ดูที่แท็บเครื่อง)")));
    });

    var pick = open[0];
    if (!pick || pick.notReady.length === DAYS[pick.d].main.length) {
      if (pick) why.push(DAYS[pick.d].name + t(" ยังฟื้นไม่ครบ ") + RECOVER_H + t(" ชม. (") + names(pick.notReady, MUSCLES) + ")");
      var extra = capPlanMinutes(extraItems([], S.energy === "tired"), S.prefs.minutes, S.prefs.rest);
      if (extra.length) {
        why.unshift(t("แอปแนะนำให้พักวันนี้ แต่คุณเพิ่มท่าเอง เล่นเบา ๆ และหยุดถ้ารู้สึกผิดปกติ"));
        return { rest: false, restAdvice: true, day: extra[0].e.day, items: extra, why: why.concat(skipped), cut: [], skipped: skippedToday() };
      }
      return { rest: true, why: why.concat(skipped) };
    }

    var D = DAYS[pick.d], tired = S.energy === "tired";
    if (!lastDay) why.push(t("ยังไม่มีประวัติ เริ่มจาก ") + D.name);
    D.main.forEach(function (m) {
      if (pick.notReady.indexOf(m) >= 0) why.push(MUSCLES[m] + t(" ฝึกไป ") + fmtH(hoursSince(lt[m])) + t(" ที่แล้ว ยังไม่ครบ ") + RECOVER_H + t(" ชม. จึงลดเซ็ต"));
      else if (lt[m]) why.push(MUSCLES[m] + t(" พักมา ") + fmtH(hoursSince(lt[m])) + t(" พร้อมแล้ว"));
    });
    cands.forEach(function (c) {
      if (c === pick || c.blocked) return;
      if (c.notReady.length) why.push(DAYS[c.d].name + t(" ยังไม่ฟื้น: ") + names(c.notReady, MUSCLES) + t(" เพิ่งฝึก"));
    });
    why = why.concat(skipped);
    if (S.slot !== "any") why.push(S.slot === "am" ? t("ช่วงเช้าเลือกเฉพาะช่วงบน") : t("ช่วงเย็นเลือกเฉพาะขา"));
    if (tired) why.push(t("วันนี้เหนื่อย: เหลือ 2 เซ็ต และไม่เพิ่มน้ำหนัก"));
    if (!why.length) why.push(D.th + t(" พร้อมทั้งหมด และเป็นคิวต่อจาก ") + (lastDay ? DAYS[lastDay].name : t("ครั้งก่อน")) + t(" ตามลำดับ PUSH → PULL → LEGS"));

    var cut = [];
    EX.forEach(function (e) { if (e.day === pick.d && S.off.indexOf(e.id) < 0) { var st = exStatus(e); if (st.out) cut.push(e.name + " (" + st.out + ")"); } });

    // a long run in the last 24 h already worked the legs
    var runKm = 0, runTs = 0;
    S.runs.forEach(function (r) { if (hoursSince(r.ts) < 24) { runKm += r.km; runTs = Math.max(runTs, r.ts); } });
    var runTired = pick.d === "legs" && runKm >= 5;
    if (runTired) why.push(t("วิ่งไป ") + (Math.round(runKm * 10) / 10) + t(" กม. เมื่อ ") + fmtH(hoursSince(runTs)) + t(" ที่แล้ว ลดเซ็ตขา 1 เซ็ต"));

    var items = pick.avail.map(function (e) {
      var st = exStatus(e);
      var sets = firstWeekLevel() === 0 ? 2 : 3;
      if (tired) sets = 2;
      if (st.light) sets = Math.max(2, sets - 1);
      if (e.m.some(function (m) { return pick.notReady.indexOf(m) >= 0; })) sets = Math.max(2, sets - 1);
      if (runTired) sets = Math.max(2, sets - 1);
      return { e: e, sets: sets, light: st.light || null, sug: suggest(e, tired) };
    }).filter(function (it) { return S.today.skip.indexOf(it.e.id) < 0; });
    items = capPlanMinutes(items.concat(extraItems(items, tired)), S.prefs.minutes, S.prefs.rest);
    return { rest: false, day: pick.d, items: items, why: why, cut: cut, skipped: skippedToday() };
  }

suggest:
function suggest(e, tired) {
    var last = lastEntry(e.id);
    // older saves may hold sets logged at 0 kg: treat them like a first time rather than "add 2.5 kg to 0"
    if (last && e.t === "kg" && !last.sets.some(function (s) { return s.kg > 0; })) last = null;
    if (!last) {
      var level = S.prefs && S.prefs.level;
      if (Number.isInteger(level) && (!S.log.length || Date.now() - S.log[0].ts < 7 * 864e5)) {
        var startReps = e.t === "sec" ? [15, 20, 30, 40][level] : e.t === "kg" ? [8, 10, 12, 12][level] : [3, 5, 10, 12][level];
        return { kg: "", reps: startReps, tip: e.t === "kg" ? tf(t("เลือกน้ำหนักเบาที่ทำได้ {n} ครั้งแบบยังเหลือแรง 2 ครั้ง"), { n: startReps }) : tf(t("เริ่มที่ {n} และหยุดเมื่อท่าเสีย"), { n: startReps + " " + unit(e) }) };
      }
      if (e.t === "kg") return { kg: "", reps: HI, tip: t("ครั้งแรก: เลือกน้ำหนักที่ทำได้ ") + HI + t(" ครั้งแบบยังเหลือแรงอีก 2 ครั้ง") };
      if (e.t === "sec") return { kg: "", reps: 30, tip: t("เริ่มที่ 30 วินาที ลำตัวตรง") };
      return { kg: "", reps: 10, tip: t("เริ่มที่ 10 ครั้ง ลงให้อกเกือบแตะพื้น") };
    }
    var reps = last.sets.map(function (s) { return s.reps || 0; });
    var minR = Math.min.apply(null, reps), maxR = Math.max.apply(null, reps);
    if (e.t !== "kg") {
      var add = e.t === "sec" ? 5 : 1;
      if (tired) return { kg: "", reps: maxR, tip: t("เหนื่อย: เท่าครั้งก่อน (") + maxR + unit(e) + ")", keep: true };
      return { kg: "", reps: maxR + add, tip: t("ครั้งก่อน ") + maxR + (e.t === "sec" ? t(" วิ") : t(" ครั้ง")) + t(" ลองเพิ่มเป็น ") + (maxR + add) };
    }
    var kg = Math.max.apply(null, last.sets.map(function (s) { return s.kg || 0; }));
    if (minR >= HI && !tired) return { kg: kg + STEP, reps: LO, tip: t("ครั้งก่อนครบ ") + HI + t(" ครั้งทุกเซ็ตที่ ") + kg + t(" กก. เพิ่มเป็น ") + (kg + STEP) + t(" กก.") };
    if (minR >= HI && tired) return { kg: kg, reps: HI, tip: t("ครบแล้วแต่วันนี้เหนื่อย คงไว้ที่ ") + kg + t(" กก."), keep: true };
    if (minR < LO) return { kg: kg, reps: LO, tip: t("ครั้งก่อนบางเซ็ตไม่ถึง ") + LO + t(" ครั้ง คงไว้ที่ ") + kg + t(" กก. ให้ถึง ") + LO + t(" ก่อน"), keep: true };
    return { kg: kg, reps: Math.min(HI, minR + 1), tip: t("คงไว้ที่ ") + kg + t(" กก. พยายามเพิ่มครั้งละ 1 จนครบ ") + HI, keep: true };
  }

exStatus:
function exStatus(e) {
    // returns {out: reason} or {light: reason} or {}
    for (var i = 0; i < e.m.length; i++) if (bodyState("m", e.m[i]) === "pain") return { out: t("เจ็บ") + MUSCLES[e.m[i]] };
    for (var j = 0; j < e.j.length; j++) if (bodyState("j", e.j[j]) === "pain") return { out: t("เจ็บ") + JOINTS[e.j[j]] };
    if (bodyState("m", e.m[0]) === "sore") return { out: MUSCLES[e.m[0]] + t("เมื่อย") };
    for (var k = 1; k < e.m.length; k++) if (bodyState("m", e.m[k]) === "sore") return { light: MUSCLES[e.m[k]] + t("เมื่อย ลด 1 เซ็ต") };
    return {};
  }

lastTrained:
function lastTrained() { // muscle -> latest timestamp
    var out = {};
    S.log.forEach(function (s) {
      s.entries.forEach(function (en) {
        var e = EXBY[en.ex]; if (!e || !en.sets.length) return;
        e.m.forEach(function (m) { if (!out[m] || s.ts > out[m]) out[m] = s.ts; });
      });
    });
    return out;
  }
